// Anti-pattern 1: Using subtraction difference trick in compareTo (vulnerable to integer overflow!)
// Anti-pattern 2: Violating the consistency between compareTo and equals
import java.math.BigDecimal;
import java.util.HashSet;
import java.util.TreeSet;

public class IntegerComparatorPoint implements Comparable<IntegerComparatorPoint> {
    private final int value;
    public IntegerComparatorPoint(int val) { this.value = val; }

    // Bug: If this.value is Integer.MIN_VALUE and o.value is positive,
    // subtraction underflows and returns a positive integer!
    @Override
    public int compareTo(IntegerComparatorPoint o) {
        return this.value - o.value; // Overflows!
    }
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        // Example of consistency violation with BigDecimal:
        BigDecimal b1 = new BigDecimal("1.0");
        BigDecimal b2 = new BigDecimal("1.00");

        // b1.equals(b2) is false (different scale)
        // But b1.compareTo(b2) == 0!
        // In HashSet (uses equals): size is 2!
        // In TreeSet (uses compareTo): size is 1! Dangerous discrepancy!
    }
}

right_code.class:
// Modern, robust compareTo using Java 8 Comparator construction methods
import java.util.Comparator;
import static java.util.Comparator.*;

public final class PhoneNumber implements Comparable<PhoneNumber> {
    private final short areaCode, prefix, lineNum;

    public PhoneNumber(int areaCode, int prefix, int lineNum) {
        this.areaCode = (short) areaCode;
        this.prefix   = (short) prefix;
        this.lineNum  = (short) lineNum;
    }

    // Static comparator construction chaining
    private static final Comparator<PhoneNumber> COMPARATOR =
        comparingInt((PhoneNumber pn) -> pn.areaCode)
            .thenComparingInt(pn -> pn.prefix)
            .thenComparingInt(pn -> pn.lineNum);

    @Override
    public int compareTo(PhoneNumber pn) {
        return COMPARATOR.compare(this, pn);
    }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        PhoneNumber p1 = new PhoneNumber(707, 867, 5309);
        PhoneNumber p2 = new PhoneNumber(707, 867, 5310);

        System.out.println(p1.compareTo(p2) < 0); // true: safe and clear natural ordering
    }
}
